/bin/zsh -lc "node - <<'NODE'
const v=[1214.424,1209.525,1213.952,1223.788,1226.207,1230.633,1232.489,1235.329,1235.008,1235.943,1221.808,1229.956,1236.302];
const d=v.slice(1).map((x,i)=>x-v[i]);
const mean=d.reduce((a,b)=>a+b,0)/d.length;
const sd=Math.sqrt(d.map(x=>(x-mean)**2).reduce((a,b)=>a+b,0)/(d.length-1));
console.log(d.map(x=>x.toFixed(3)).join(', '));
console.log('mean',mean.toFixed(3),'sigma',sd.toFixed(3),'half', (1.28*sd).toFixed(3));
console.log('jan-aug25', (1235.329-1214.424).toFixed(3));
NODE"

